style.css:
@-moz-document domain("play.google.com") {
:root{
    --bg:#000000;           /* background base */
    --matrix-green:#00ff66; /* bright matrix green */
    --dim-green:#178f3a;    /* darker green */
    --accent: #39ff6b;      /* glow accent */
    --card-bg: rgba(0,10,0,0.6);
    --glass: rgba(0,0,0,0.45);
    --muted: rgba(180,255,200,0.08);
    --speed: 18s;           /* matrix rain animation speed */
    --font-mono: "Lucida Console", "Courier New", monospace;
  }

  /* --- Global reset / base --- */
  html, body {
    background: var(--bg) fixed;
    color: var(--matrix-green) !important;
    font-family: var(--font-mono) !important;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  /* matrix rain background using pseudo element */
  body::before{
    content: "";
    position: fixed;
    z-index: 0;
    inset: 0;
    pointer-events: none;
    background-image:
      linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.6) 70%),
      repeating-linear-gradient(0deg,
        rgba(0,0,0,0) 0 10px,
        rgba(0,0,0,0.02) 10px 20px);
    mix-blend-mode: normal;
  }

  /* animated "rain" overlay (subtle) */
  body::after{
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    background:
      radial-gradient(ellipse at 10% 10%, rgba(0,255,120,0.02), transparent 10%),
      linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.7) 100%);
    background-size: 1200px 1200px, cover;
    animation: drift var(--speed) linear infinite;
    pointer-events: none;
    opacity: 0.55;
    filter: contrast(1.1) saturate(1.2);
  }

  @keyframes drift{
    0%{ background-position: 0 0, 0 0; }
    100%{ background-position: -1200px 2400px, 0 0; }
  }

  /* Page content sits over the effect */
  #fcxH9b { /* top container id observed on Play - apply generic fallback too */
    position: relative;
    z-index: 1;
  }

  /* Make main app shell darker and slightly translucent glass */
  header, nav, .Z1hOCe, .u3bW4e, .M2UAec, .VfPpkd-Jh9lGc {
    background: linear-gradient(180deg, rgba(0,0,0,0.6), rgba(0,0,0,0.4)) !important;
    backdrop-filter: blur(4px) saturate(1.1);
    color: var(--matrix-green) !important;
    border-color: rgba(0,255,120,0.06) !important;
  }

  /* Cards / tiles */
  .ImZGtf, .VfPpkd-Ne0eGc, .WHE7ib, .Mx1hLc {
    background: linear-gradient(180deg, rgba(0,16,0,0.55), rgba(0,6,0,0.35)) !important;
    border: 1px solid rgba(0,255,120,0.06) !important;
    box-shadow: 0 6px 18px rgba(0,0,0,0.6), 0 0 10px rgba(0,255,120,0.02) inset !important;
    color: var(--matrix-green) !important;
  }

  /* App titles, headings, and primary text */
  h1, h2, h3, h4, .WsMG1c {
    color: var(--matrix-green) !important;
    text-shadow: 0 0 8px rgba(0,255,120,0.06);
    letter-spacing: 0.2px;
    font-weight: 600;
  }

  /* Buttons / primary actions */
  button, .VfPpkd-Bz112c-LgbsSe, .T4LgNb {
    background: linear-gradient(180deg, rgba(9,60,9,0.9), rgba(0,0,0,0.4));
    color: black !important;
    color: #001600 !important;
    box-shadow: 0 6px 18px rgba(0,255,120,0.04);
    border: 1px solid rgba(0,255,120,0.09);
    border-radius: 6px;
    font-weight: 700;
  }

  /* Links glow on hover */
  a, .aQx {
    color: var(--matrix-green) !important;
    text-decoration: none !important;
    transition: text-shadow .12s, color .12s;
  }
  a:hover {
    text-shadow: 0 0 12px var(--accent);
    color: #b7ffce !important;
  }

  /* Icons and images: desaturate and add faint green overlay */
  img, svg {
    filter: grayscale(20%) contrast(0.95) brightness(0.9) saturate(0.85);
    opacity: 0.95;
  }

  /* Option: hide heavy hero images to emphasize matrix aesthetic */
  .Sz8oQd, .dzZ2md, .f1W7rb, .bAhLNe {
    background: none !important;
    background-image: none !important;
    color: var(--matrix-green) !important;
  }

  /* App listing badges and price chips */
  .VfPpkd-kBDsod, .VfPpkd-Bz112c-LgbsSe {
    background: rgba(0,0,0,0.6) !important;
    border: 1px solid rgba(0,255,120,0.06) !important;
    color: var(--matrix-green) !important;
  }

  /* Subtext / metadata */
  .b8cIId, .IyZ38b, .ZjGz6 {
    color: rgba(180,255,200,0.85) !important;
    opacity: 0.9;
    font-size: 12px;
  }

  /* Search box - make it more terminal-like */
  input[type="search"], input[type="text"], .gLFyf {
    background: rgba(0,8,0,0.7) !important;
    color: var(--matrix-green) !important;
    border: 1px solid rgba(0,255,120,0.08) !important;
    box-shadow: 0 0 18px rgba(0,255,120,0.02) inset;
    caret-color: var(--accent) !important;
    font-family: var(--font-mono) !important;
  }

  /* Footer tweaks */
  footer, .kHssDb {
    background: linear-gradient(180deg, rgba(0,0,0,0.45), rgba(0,0,0,0.6));
    color: rgba(160,255,170,0.9);
    border-top: 1px solid rgba(0,255,120,0.03);
  }

  /* Inputs, selects, textareas */
  select, textarea {
    background: rgba(0,8,0,0.65) !important;
    color: var(--matrix-green) !important;
    border: 1px solid rgba(0,255,120,0.06) !important;
    font-family: var(--font-mono) !important;
  }

  /* subtle scanline overlay across the page for retro effect */
  :root::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 1;
    background-image: linear-gradient(transparent 90%, rgba(0,0,0,0.08) 100%);
    background-size: 100% 2px;
    pointer-events: none;
    mix-blend-mode: overlay;
    opacity: 0.15;
  }

  /* Chromey / Material specific: ensure interactive elements are still usable */
  .VfPpkd-Jh9lGc, .VfPpkd-Jh9lGc-rymPhb {
    color: var(--matrix-green) !important;
  }

  /* Make overlays and dialogs match theme */
  .Kj-JD, .eVqMbd, .YWH3Vb {
    background: linear-gradient(180deg, rgba(2,8,0,0.98), rgba(0,0,0,0.9)) !important;
    color: var(--matrix-green) !important;
    border: 1px solid rgba(0,255,120,0.06) !important;
  }

  /* small cards: remove bright colors from badges */
  .T4LgNb .VfPpkd-Jh9lGc {
    color: #001600 !important;
  }

  /* reduce bright logos prominence (optional): hide if you want strict matrix look */
  /* .ZjFb7c { display: none !important; } */

  /* Make sure z-index of UI > background effects */
  header, nav, main, footer, .ImZGtf {
    position: relative;
    z-index: 2;
  }

  /* Accessibility: ensure contrast for critical UI elements */
  .VfPpkd-Bz112c-LgbsSe[aria-disabled="true"] {
    opacity: 0.45 !important;
    filter: grayscale(40%);
  }

  /* ===== Optional: terminal-like marquee for app titles (subtle) ===== */
  .WsMG1c {
    text-transform: uppercase;
    letter-spacing: 0.6px;
  }

  /* ===== responsive tweaks ===== */
  @media (max-width: 720px) {
    :root { --speed: 12s; }
    h1, h2, h3 { font-size: 1rem; }
    .ImZGtf { padding: 8px !important; }
  }
}
